(()=>{
const data={};let user=null,profile={};
function updateProfile(p){profile=p;if(user)user.name=p.name||user.name;const link=document.querySelector('.account-navigation');if(link){link.replaceChildren();link.setAttribute('aria-label','My profile');link.title='My profile';if(p.photo){const img=document.createElement('img');img.src=p.photo;img.alt='';link.append(img)}else link.textContent=Array.from((user?.username||'?').trim())[0].toUpperCase();}document.getElementById('annual-profile-review')?.remove();if(p.review_due&&user?.role!=='admin'&&location.pathname!=='/account.html'){const note=document.createElement('p');note.id='annual-profile-review';note.style.cssText='padding:12px 5vw;margin:0;background:#fff3cd';const a=document.createElement('a');a.href='/account.html';a.textContent='Please review your current study year or training stage in My profile.';note.append(a);document.querySelector('header')?.after(note);}}

async function request(path,body){const r=await fetch(path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json','X-Quiz-Admin':'1'}:{},body:body?JSON.stringify({...body,account_id:user?.id}):undefined});const result=await r.json();if(!r.ok){if(r.status===401)location.href='/login.html';throw Error(result.error||'Request failed.')}return result;}
const ready=(async()=>{const result=await request('/api/account');user=result.user;if(!user){location.href='/login.html';throw Error('Please sign in.')}Object.assign(data,await request('/api/study'));let header=document.querySelector('header');if(!header){header=document.createElement('header');document.body.prepend(header);}if(header){
 header.replaceChildren();
 const home=document.createElement('a');home.className='brand home-brand';home.href=user.role==='admin'?'/admin-home.html':'/sets.html';home.title='Go to home';home.setAttribute('aria-label','DrillSpace — Go to home');
 const mark=document.createElement('span');mark.className='mark';mark.textContent='D';mark.setAttribute('aria-hidden','true');const title=document.createElement('strong');title.textContent='DrillSpace';home.append(mark,title);header.append(home);
 const page=location.pathname;
 const learningPages=['/sets.html','/history.html','/rankings.html'];
 if(learningPages.includes(page)||(page==='/account.html'&&user.role!=='admin')){
  const nav=document.createElement('nav');nav.className='learner-navigation';nav.setAttribute('aria-label','Learning navigation');
  for(const [href,label] of [['/sets.html','Learning'],['/history.html','My attempts'],['/rankings.html','Rankings']]){const link=document.createElement('a');link.href=href;link.textContent=label;if(page===href)link.setAttribute('aria-current','page');nav.append(link)}header.append(nav);
 }

 const account=document.createElement('a');account.className='secondary account-navigation';account.href='/account.html';account.textContent=user.name+' · Account';header.append(account);
 const style=document.createElement('style');style.textContent='header{display:flex;align-items:center;justify-content:flex-start;gap:18px;flex-wrap:wrap;height:auto;min-height:84px}.home-brand{display:inline-flex;align-items:center;gap:12px;text-decoration:none;color:#172a44;border-radius:8px;padding:4px}.home-brand:hover{color:#2454d6;background:#f0f5ff}.home-brand:focus-visible{outline:3px solid #2454d6;outline-offset:4px}.account-navigation{margin-left:auto;width:44px;height:44px;padding:0!important;border-radius:50%;display:flex;align-items:center;justify-content:center;overflow:hidden;background:#e7eeff;font-weight:bold;flex-shrink:0}.account-navigation img,.profile-avatar img{width:100%;height:100%;object-fit:cover}.profile-avatar{display:flex;align-items:center;justify-content:center;width:88px;height:88px;border-radius:50%;overflow:hidden;background:#e7eeff;font-size:28px;flex-shrink:0}header [aria-current=page]{background:#e7eeff;border-color:#2454d6}header .learner-navigation{display:flex;align-items:stretch;gap:12px;align-self:stretch;margin-left:22px}header .learner-navigation a{display:flex;align-items:center;padding:15px 12px;border-bottom:3px solid transparent;color:#536b8b;text-decoration:none;font-size:14px;font-weight:600}header .learner-navigation a[aria-current=page]{background:transparent;color:#172a44;border-bottom-color:#2454d6}header .learner-navigation a:hover{color:#2454d6;background:#f5f8ff}@media(max-width:650px){header .learner-navigation{order:3;flex-basis:100%;margin-left:0;gap:6px}header .learner-navigation a{padding:10px 12px}header:has(.learner-navigation){padding-top:12px;gap:8px 16px}}';document.head.append(style);
 }try{updateProfile(await request('/api/profile'))}catch(e){updateProfile({name:user.name})}return user})();
window.Account={ready,updateProfile,get user(){return user},get(key,fallback){return data[key]?.value??fallback},async save(key,value){const result=await request('/api/study',{key,value,revision:data[key]?.revision||0});data[key]={value,revision:result.revision};return value},request};
})();
